    def _download(self, **kwargs):
        package_name = kwargs['package']
        version_number = kwargs.get('version_number', None)
        alias = kwargs.get('alias', 'default')
        timeout = kwargs.get('timeout', 1200)
        # was_ssh_alias = kwargs.get('was_ssh_alias', 'default')

        if package_name.lower() == 'auto':
            config_device = kwargs["config_device"]
            config_info = get_config_variable(["ems", config_device])
            netact_info = {"ip": config_info["was_host"], "user": config_info["web_user"],
                           "password": config_info["was_ssh_pass"], "prompt": "$"}
            wft_profile = kwargs['wft_profile']
            download_url, version_id, package_template = self.build_download.find_latest_build(wft_profile)
            logger.debug("download url {} latest_buildnum {} package_template {}".format(
                download_url, version_id, package_template))
            if kwargs.get('latest_build_num', None):
                version_id = version_number + "_ENB_" + kwargs.get('latest_build_num')
            package_name = self._download_and_import_build(package_name=package_name,
                                                           latest_buildnum=version_id,
                                                           alias=alias,
                                                           build_download=True,
                                                           package_template=package_template,
                                                           netact_info=netact_info,
                                                           download_url=download_url, download_path="/d/oss/global/swmanager/swm_temp", 
                                                           wft_profile=wft_profile)
        else:
            if re.search(r'SBTS00\w\D*_9999', package_name) and version_number:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "").replace("SBTS00",
                                                                                                     version_number)
            else:
                version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "")

            package_name = self._download_and_import_build(package_name=package_name,
                                                           latest_buildnum=version_id,
                                                           alias=alias,
                                                           build_download=False)
        logger.info("Package name to download is {}".format(version_id))
        bts_moc_id = kwargs.get("bts_moc_id", self.bts_moc_id)
        logger.info("BTS moc id is {}".format(bts_moc_id))

        return self._perform_swm_download(version_id, timeout, alias, bts_moc_id=bts_moc_id)

    def _perform_swm_download(self, package_name, timeout, alias, bts_moc_id=None):
        try:
            # resp = self.netact_factory.swm_operations.swm_download(mo_name=self.bts_moc_id,
            #                                                        package_name=package_name,
            #                                                        alias=alias)
            resp = self.netact_factory.netact.download_sw(dist_names=bts_moc_id, package_name=package_name,
                                                          timeout=timeout,
                                                          alias=alias)
            # resp = self.netact_factory.netact.start_swm_operation(operation_type='download',
            #                                                       dist_names=self.bts_moc_id,
            #                                                       package_name=package_name,
            #                                                       alias=alias)
            logger.debug("*********************Response from swm_download {}".format(resp))
        except Exception as e:
            logger.debug("*************** swm download threw an exception: {0}. Attempting to retry the "
                         "operation".format(e))
            time.sleep(300)
            # self.netact_factory.swm_operations.swm_download(mo_name=self.bts_moc_id,
            #                                                 package_name=package_name, alias=alias)
            resp = self.netact_factory.netact.download_sw(dist_names=bts_moc_id, package_name=package_name,
                                                          timeout=timeout,
                                                          alias=alias)
            # resp = self.netact_factory.netact.start_swm_operation(operation_type='download',
            #                                                       dist_names=self.bts_moc_id,
            #                                                       package_name=package_name,
            #                                                       alias=alias)
        finally:
            return resp

    def start_swm_operation_and_wait_untill_complete(self, operation_type, package_name, timeout, alias, bts_moc_id=None):

        operation_id = self.netact_factory.netact.start_swm_operation(operation_type=operation_type,
                                                                      dist_names=bts_moc_id,
                                                                      package_name=package_name, alias=alias)

        self.netact_factory.netact.get_progress_of_swm_operation(operation_id=operation_id, alias=alias)
        try:
            self.netact_factory.netact.wait_for_swm_operation(operation_id=operation_id, timeout=timeout, alias=alias)
        except Exception as e:
            logger.debug("Exception raised: {}. Getting progress of swm operation".format(e))
            self.netact_factory.netact.get_progress_of_swm_operation(operation_id=operation_id, alias=alias)

    def _download_and_import_build(self, package_name, latest_buildnum, alias,
                                   build_download=True, **kwargs):

        max_try = 3
        is_imported = self.netact_factory.netact.is_imported(version_id=latest_buildnum, alias=alias)
        logger.debug("#### Is imported {}".format(is_imported))
        if not is_imported:
            kwargs['latest_buildnum'] = latest_buildnum
            package, package_name, build_version = self._download_build(**kwargs) if build_download else \
                self._ret_build_info(package_name)
            try:
                # self.netact_factory.swm_importer.import_build(file_path=package_name,
                #                                               clean_temp_folder_after_import=False,
                #                                               mo_type='MRBTS', alias=alias)
                logger.debug("Package_name is {}".format(package_name))
                logger.debug("Importing the builds")
                self.netact_factory.netact.import_build(package_name, alias=alias)
            except Exception as e:
                while max_try != 0:
                    logger.debug("Exception {} while importing {}".format(e, package_name))
                    logger.debug("Retrying to import {}".format(package_name))
                    self.netact_factory.netact.import_build(package_name, alias=alias)
                    time.sleep(2)
                    is_imported = self.netact_factory.netact.is_imported(version_id=latest_buildnum, alias=alias)
                    max_try -= 1
                    if is_imported:
                        break
                else:
                    raise FailedToImportBuild
            logger.debug("#### successfully imported build {}".format(package_name))
            return build_version
        else:
            logger.debug("Package {} is already imported".format(package_name))
            return latest_buildnum

    def _ret_build_info(self, package_name):
        return None, package_name

    def _download_build(self, **kwargs):
        latest_buildnum = kwargs["latest_buildnum"]
        download_url = kwargs["download_url"]
        package_template = kwargs["package_template"]
        netact_info = kwargs["netact_info"]
        download_path = kwargs.get("download_path", "execution_logs")
        ssh_session = self._start_ssh_to_dut(netact_info)
        try:
            package, package_name, build_version = self.build_download.download_latest_build(
                latest_buildnum, download_url, package_template, download_path, ssh_session)
            logger.info("Build download is successful")
            logger.info("Package is {} AND package_name is {}".format(package, package_name))
            return package, package_name, build_version
        except FailedToDownloadBuild as e:
            raise FailedToDownloadBuild("Failed to download build {}".format(e))
        except Exception as e:
            raise Exception("Caught exception from framework {}".format(e))

    def _activate(self, **kwargs):
        package_name = kwargs['package']
        version_number = kwargs.get('version_number', None)
        alias = kwargs.get('alias', 'default')
        timeout = kwargs.get('timeout', 600)
        bts_moc_id = kwargs.get("bts_moc_id", self.bts_moc_id)
        # bts_moc_distname = 'PLMN-PLMN/MRBTS-{bts_id}'.format(
        # bts_id=get_config_variable(['bts_id']))
        # self.netact_factory.swm_operations.swm_activate(mo_name=self.bts_moc_id, package_name=package_name,
        #                                                 alias=alias)
        if re.search(r'SBTS00\w\D*_9999', package_name) and version_number:
            version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "").replace("SBTS00",
                                                                                                 version_number)
        else:
            version_id = package_name.replace("_release_BTSSM_downloadable_A54.zip", "")
        return self.netact_factory.netact.activate_sw(dist_names=bts_moc_id, package_name=version_id,
                                                      timeout=timeout, alias=alias)

    def rollback_sw(self, **kwargs):
        """
        *Keyword:* Rollback Software From Netact
        Execute rollback operation on given distnames.
        """
        dist_names = kwargs["dist_names"]
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 600)

        return self.netact_factory.netact.rollback_sw(dist_names=dist_names, alias=alias, timeout=timeout)

    @staticmethod
    def _start_ssh_to_dut(remote_device):
        prompt = remote_device['prompt']
        if prompt is None:
            prompt = '#'
        ssh_client = SSHClient(remote_device['ip'], port=22, prompt=prompt, timeout=10)
        ssh_client.login(remote_device['user'],
                         remote_device['password'])
        return ssh_client